var _markdown = "\n\n`sa` · 扩展 `NewOpcodes` · 需 CLEO + NewOpcodes\n\n车灯损伤、车类、dummy 点、抛射物。写法见 [Lua](/docs/cleo/syntax) / [Redux](/docs/cleo/syntax-redux)。\n\n## 车灯损伤 [#车灯损伤]\n\n<Opcode id=\"0D5C\" name=\"GET_CAR_LIGHT_DAMAGE_STATUS\">\n  读指定车灯（大灯/尾灯等）是否损坏。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0D5C GET_CAR_LIGHT_DAMAGE_STATUS\n      in: car, light\n      out: damageState\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local broken = getCarLightDamageStatus(car, light)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const damageState = native(0x0D5C, car, light)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0D5D\" name=\"SET_CAR_LIGHT_DAMAGE_STATUS\">\n  写指定车灯损坏状态。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0D5D SET_CAR_LIGHT_DAMAGE_STATUS\n      in: car, light, damageState\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      setCarLightDamageStatus(car, light, true)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      native(0x0D5D, car, light, damageState)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 车类 / dummy [#车类--dummy]\n\n<Opcode id=\"0D5E\" name=\"GET_VEHICLE_CLASS_AND_SUBCLASS\">\n  取载具 class / subclass。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0D5E GET_VEHICLE_CLASS_AND_SUBCLASS\n      in: vehicle\n      out: class, subclass\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      local cls, sub = getVehicleClassAndSubclass(car)\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      const { class: vehicleClass, subclass } = native(0x0D5E, vehicle)\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n<Opcode id=\"0D5F\" name=\"GET_VEHICLE_DUMMY_POSN\">\n  取车 dummy 点坐标（世界或局部，由 `position` / `invertX` 控制）。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0D5F GET_VEHICLE_DUMMY_POSN\n      in: vehicle, dummyElement, position, invertX\n      out: x, y, z\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if getVehicleDummyPosn(car, dummy, posType, false) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (native(0x0D5F, vehicle, dummyElement, position, invertX)) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n\n## 抛射物 [#抛射物]\n\n<Opcode id=\"0D60\" name=\"CREATE_PROJECTILE\">\n  从实体向目标点/实体创建抛射物（导弹等）。用在 `if` 里。\n\n  <CodeBlockTabs defaultValue=\"OP\">\n    <CodeBlockTabsList>\n      <CodeBlockTabsTrigger value=\"OP\">\n        OP\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Lua\">\n        Lua\n      </CodeBlockTabsTrigger>\n\n      <CodeBlockTabsTrigger value=\"Redux\">\n        Redux\n      </CodeBlockTabsTrigger>\n    </CodeBlockTabsList>\n\n    <CodeBlockTab value=\"OP\">\n      ```text\n      0D60 CREATE_PROJECTILE\n      in: type, launchedFromEntity, originX, originY, originZ, targetX, targetY, targetZ, targetEntity, force\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Lua\">\n      ```lua\n      if createProjectile(ptype, from, ox, oy, oz, tx, ty, tz, target, force) then\n      end\n      ```\n    </CodeBlockTab>\n\n    <CodeBlockTab value=\"Redux\">\n      ```js\n      if (\n        native(\n          0x0D60,\n          type, launchedFromEntity,\n          originX, originY, originZ,\n          targetX, targetY, targetZ,\n          targetEntity, force\n        )\n      ) {\n      }\n      ```\n    </CodeBlockTab>\n  </CodeBlockTabs>\n</Opcode>\n";
